$historyPerson=static function(mixed$id)use($personOptions,$historyText):string{if($id===null||$id==='')return$historyText('Keine Zuordnung');return$personOptions[$id]??$historyText('Ursprüngliche Person nicht mehr verfügbar: {id}',['id'=>(string)$id]);};
