<details id="inventory-item-history" class="iv-editor-panel iv-history-panel" data-inventory-panel="history" <?= array_key_exists('item_history_page',$_GET)?'open':'' ?>><summary><span><strong><?= e($historyText('Frühere Angaben ansehen · {count}',['count'=>(string)$historyList['total']])) ?></strong><small><?= e($historyText('Gespeicherte Zuständigkeit und Eigentumsart im Zeitverlauf')) ?></small></span></summary><div class="iv-editor-body">
<p><?= e($historyText('Die Zuordnungen stammen aus den jeweiligen gespeicherten Angaben. Angezeigte Personennamen werden aus den heute verfügbaren eigenen Kontakten nachgeschlagen.')) ?></p><p data-inventory-item-history-summary><?= e($historyText('{count} frühere Angaben · Seite {page} von {pages}',['count'=>(string)$historyList['total'],'page'=>(string)$historyList['page'],'pages'=>(string)$historyList['pages']])) ?></p>
<div class="iv-history-cards"><?php foreach($historyList['rows']as$row):$snapshot=$row['details'][1]; ?><article data-inventory-item-history="<?= (int)$row['sequence'] ?>"><header><h3><?= e($historyText('Gespeichert: {date}',['date'=>(new DateTimeImmutable($row['happened_at']))->setTimezone(new DateTimeZone('Europe/Berlin'))->format('d.m.Y H:i')])) ?></h3></header><dl><div><dt><?= e($historyText('Zuständigkeit')) ?></dt><dd><?= e($historyPerson($snapshot['responsible_id']??'')) ?></dd></div><div><dt><?= e($historyText('Bereich / Abteilung')) ?></dt><dd><?= e(($snapshot['department']??'')!==''?$snapshot['department']:$historyText('Nicht angegeben')) ?></dd></div><div><dt><?= e($historyText('Eigentum')) ?></dt><dd><?= e($historyText(($snapshot['ownership']??'club')==='club'?'Vereinseigentum':'Fremde Leihgabe')) ?></dd></div><?php if(($snapshot['ownership']??'club')==='third_party'): ?><div><dt><?= e($historyText('Eigentümer bei fremder Leihgabe')) ?></dt><dd><?= e($historyPerson($snapshot['owner_id']??'')) ?></dd></div><?php endif ?></dl><footer><?= e($ivActorNames->label($row['actor_id'],$historyText)) ?></footer></article><?php endforeach;if(!$historyList['rows']): ?><p><?= e($historyText('Keine früheren Angaben gefunden.')) ?></p><?php endif ?></div>
<?php if($historyList['pages']>1): ?><nav aria-label="<?= e($historyText('Seiten früherer Angaben')) ?>"><?php if($historyList['page']>1): ?><a class="btn btn-outline theme-secondary" href="<?= e(url($historyRoute+['item_history_page'=>(string)($historyList['page']-1)])) ?>#inventory-item-history"><?= e($historyText('Vorherige Angaben')) ?></a><?php endif;if($historyList['page']<$historyList['pages']): ?><a class="btn btn-outline theme-secondary" href="<?= e(url($historyRoute+['item_history_page'=>(string)($historyList['page']+1)])) ?>#inventory-item-history"><?= e($historyText('Weitere Angaben')) ?></a><?php endif ?></nav><form method="get" action="#inventory-item-history"><?php foreach($historyRoute as$key=>$value)echo hidden($key,$value); ?><label><?= e($historyText('Seite')) ?><input class="form-control" type="number" name="item_history_page" value="<?= (int)$historyList['page'] ?>" min="1" max="<?= (int)$historyList['pages'] ?>" required></label><button class="btn btn-solid theme-primary"><?= e($historyText('Seite anzeigen')) ?></button></form><?php endif ?>
</div></details>
